function role(){return D?.me.role||'';}function admin(){return role()==='dono';}function elevated(){return role()!=='operador';}
function userName(userid){return D?.users.find(x=>x.id===userid)?.name||'Usuário';}
function userById(userid){return D?.users.find(x=>x.id===userid)||{pctMontante:10,pctContas:10,goal:1000};}
// Separate financial ledgers. Old operations without type belong to Montantes.
function isContas(o){return o.type==='contas';}
function accountValues(o){
 let a=Number(o.accountDeposit||0),b=Number(o.accountWithdraw||0),c=Number(o.accountSalary||0);
 // Preserve older Conta records that used the original three fields.
 if(isContas(o)&&a===0&&b===0&&c===0&&(Number(o.deposit)||Number(o.withdraw)||Number(o.blogger))){
  return {deposit:Number(o.deposit||0),withdraw:Number(o.withdraw||0),salary:Number(o.blogger||0)};
 }
 return {deposit:a,withdraw:b,salary:c};
}
function gross(o){return isContas(o)?accountValues(o).withdraw-accountValues(o).deposit:Number(o.withdraw||0)-Number(o.deposit||0);}
function profit(o){return isContas(o)?round(gross(o)+accountValues(o).salary):round(gross(o)+Number(o.blogger||0));}
// Keep the commission rule already present in prior versions; splitting ledgers must not
// silently change the amount owed by operators.
function accountsCommission(o){
 const rate=Number(userById(o.userId).pctContas||0)/100;
 if(isContas(o))return round(Math.max(0,accountValues(o).salary)*rate);
 // Preserve the V4 calculation only for unmigrated records without a type.
 if(!o.type)return round(Math.max(0,Number(o.blogger)||0)*rate);
 return 0;
}
function svcCommission(s){return s.status==='validado'?round((Number(s.salary)||0)*((userById(s.userId).pctMontante||0)/100)):0;}
function round(v){return Math.round((Number(v)||0)*100)/100;}
function selOp(){let ops=D.operations;if(elevated()&&selectedUser!=='all')ops=ops.filter(o=>o.userId===selectedUser);return ops.filter(x=>inPeriod(x.createdAt));}
function inPeriod(dt){let d=new Date(dt),now=new Date(),start=new Date(now);start.setHours(0,0,0,0);if(period==='all')return true;if(period==='today')return d>=start;if(period==='yesterday'){let y=new Date(start);y.setDate(y.getDate()-1);return d>=y&&d<start;}if(period==='7'){start.setDate(start.getDate()-6);return d>=start;}if(period==='30'){start.setDate(start.getDate()-29);return d>=start;}if(period==='month')return d.getMonth()===now.getMonth()&&d.getFullYear()===now.getFullYear();if(period==='last'){let last=new Date(now.getFullYear(),now.getMonth()-1,1);return d.getMonth()===last.getMonth()&&d.getFullYear()===last.getFullYear();}if(period==='custom'){let y=dt.slice(0,10);return (!customStart||y>=customStart)&&(!customEnd||y<=customEnd);}return true;}
function totals(ops){
 let mont=ops.filter(o=>!isContas(o)),cont=ops.filter(isContas),sum=(a,k)=>round(a.reduce((s,o)=>s+Number(o[k]||0),0));
 let m={count:mont.length,deposit:sum(mont,'deposit'),withdraw:sum(mont,'withdraw'),blogger:sum(mont,'blogger'),profit:round(mont.reduce((s,o)=>s+profit(o),0))};
 let c={count:cont.length,deposit:round(cont.reduce((s,o)=>s+accountValues(o).deposit,0)),withdraw:round(cont.reduce((s,o)=>s+accountValues(o).withdraw,0)),salary:round(cont.reduce((s,o)=>s+accountValues(o).salary,0)),profit:round(cont.reduce((s,o)=>s+profit(o),0))};
 return {deposit:round(m.deposit+c.deposit),withdraw:round(m.withdraw+c.withdraw),blogger:m.blogger,profit:round(m.profit+c.profit),com:round(ops.reduce((s,o)=>s+accountsCommission(o),0)),mont:m,cont:c};
}
