async function api(path,options={}){let res=await fetch('/api'+path,{credentials:'same-origin',headers:options.body?{'Content-Type':'application/json'}:{},...options});let data;try{data=await res.json();}catch{throw Error('O servidor não respondeu corretamente.');}if(!res.ok){if(res.status===401&&D){D=null;renderAuth('login');}throw Error(data.error||'Falha na solicitação');}return data;}
