function divisorCard(){return `<div class="dividerbox"><div class="paneltitle" style="margin-bottom:13px"><h3>◈ Divisor de depósito</h3><span class="tag">Distribuição</span></div><div class="formrow two">${field('Valor total (R$)','divTotal','number','500',false,500)}${field('Quantidade de contas','divCount','number','5',false,5)}</div><div style="margin-top:12px">${field('Valor mínimo por conta','divMin','number','35',false,35)}</div><button class="btn primary w100" style="margin-top:11px" data-action="distribute">${ico('calc')} Distribuir valores</button><div class="divided-results"><div class="paneltitle"><h3>Resultado</h3><button class="btn sm" data-action="copydiv">${ico('copy')} Copiar</button></div><div id="divResult" class="calcmsg">Informe os valores e clique em Distribuir.</div><div id="divSum" class="tiny" style="text-align:right;margin-top:8px">Soma: —</div></div></div>`;}
