function calcPanelHtml(){if(calcTab==='montante')return `<div class="calc-controls"><div class="micro" style="color:var(--accent)">Calculadora de porcentagem</div><div class="calc-amount-only">${field('Valor do pedido (R$)','calcAmount','number','Digite o valor desejado',false,'','min="0" step="0.01"')}</div><p class="tiny" style="margin:5px 0 10px">Informe o valor para calcular a taxa automaticamente. Abaixo de ${money(D.settings.promoAt)}: ${D.settings.baseRate}%; a partir de ${money(D.settings.promoAt)}: ${D.settings.promoRate}%.</p>${field('Até quantas contas','calcCount','number','1',false,1,'min="1" max="999" step="1"')}<div class="calcresult hide"><div class="micro">Taxa aplicada: <span id="calcRate"></span></div><strong id="calcTotal">—</strong><div class="tiny">Valor a pagar</div></div></div>`;return `<div class="calc-controls"><div class="micro" style="color:var(--accent)">Calculadora de contas</div>${field('Quantidade de contas','calcCount','number','10',false,10,'min="1" max="999" step="1"')}<div class="formrow two">${field('Mínimo','calcMin','number','1',false,1)}${field('Máximo','calcMax','number','10',false,10)}</div>${field('Preço por conta (R$)','calcUnit','number','5',false,5)}<div class="calcresult"><div class="micro">Total calculado</div><strong id="calcTotal">—</strong></div></div>`;}
function dividetotal(total,count,min){
 // Work entirely in cents: no missing or extra centavos, even after repeated draws.
 const cents=Math.round(total*100),floor=Math.ceil(min*100-1e-7);
 if(!Number.isInteger(count)||count<1||count>200||!Number.isFinite(cents)||!Number.isFinite(floor)||floor<0||cents<count*floor||cents<=0)return null;
 const extra=cents-count*floor;
 if(count===1)return [cents/100];
 const weights=Array.from({length:count},()=>0.2+Math.random()*1.8);
 const sum=weights.reduce((a,b)=>a+b,0);
 let parts=weights.map(w=>floor+Math.floor(extra*w/sum));
 let remaining=cents-parts.reduce((a,b)=>a+b,0);
 for(let i=0;i<remaining;i++)parts[(i+Math.floor(Math.random()*count))%count]++;
 return parts.map(v=>v/100);
}
function calcValue(){
 let el=n=>Number(document.querySelector(`[name="${n}"]`)?.value||0),settings=D.settings,t=0,msg='',rate=0,count=Math.max(1,Math.min(999,Math.floor(el('calcCount')||1))),p=ownP();
 const replace=(pattern,args)=>pattern.replace(/\{(montante|valor|contas|preco|total|pix|nome|banco|tipo|cabecalho|recado)\}/gi,(_,k)=>String(args[k.toLowerCase()]??''));
 const pixParts={pix:p.key||'CHAVE PIX NÃO CADASTRADA',nome:p.name||'TITULAR NÃO INFORMADO',banco:p.bank||'BANCO NÃO INFORMADO',tipo:p.type.toUpperCase(),cabecalho:p.header||'PIX PARA PAGAMENTO',recado:p.note||''};
 if(calcTab==='montante'){
  const input=document.querySelector('[name="calcAmount"]'),entered=!!input&&input.value.trim()!=='';
  const amt=Math.max(0,el('calcAmount'));
  rate=amt>=settings.promoAt?settings.promoRate:settings.baseRate;
  t=round(amt*rate/100);
  if(entered&&amt>0)msg=replace(p.customMontante||settings.templateMontante,{...pixParts,montante:money(amt),valor:money(t),contas:count,total:money(t),preco:money(t)});
 }else{
  t=round(count*el('calcUnit'));
  msg=replace(p.customContas||settings.templateContas,{...pixParts,contas:count,preco:money(el('calcUnit')),total:money(t),valor:money(t)});
 }
 if(msg&&p.header&&!msg.includes(p.header))msg=p.header+'\n\n'+msg;
 if(msg&&p.note&&!msg.includes(p.note))msg=msg+'\n\n'+p.note;
 if(msg&&p.key&&!msg.includes(p.key))msg+='\n\n🔑 Chave PIX: '+p.key+'\n👤 '+(p.name||'Titular não informado')+'\n🏦 '+(p.bank||'Banco não informado');
 const totalEl=$('#calcTotal'),rateEl=$('#calcRate'),result=totalEl?.closest('.calcresult'),messageEl=$('#calcMessage'),ready=calcTab!=='montante'||!!msg;
 if(result)result.classList.toggle('hide',!ready);
 if(totalEl)totalEl.textContent=ready?money(t):'';
 if(rateEl)rateEl.textContent=ready?rate+'%':'';
 if(messageEl){messageEl.textContent=ready?msg:'';messageEl.classList.toggle('hide',!ready);}
 return msg;
}
function calcDivider(){
 const total=Number($('[name="divTotal"]')?.value||0),count=Number($('[name="divCount"]')?.value||0),minimum=Number($('[name="divMin"]')?.value||0);
 if(!Number.isFinite(total)||total<=0||!Number.isInteger(count)||count<1||count>200||minimum<0||!Number.isFinite(minimum)){
  notify('Revise o valor, o mínimo e a quantidade (até 200 contas).',true);return;
 }
 let parts=null,output='';
 for(let attempt=0;attempt<7;attempt++){
  parts=dividetotal(total,count,minimum);if(!parts)break;
  output=parts.map((v,i)=>`${i+1}. ${money(v)}`).join('\n')+'\n\nTotal: '+money(parts.reduce((a,b)=>a+b,0));
  if(output!==lastDivResult||count===1)break;
 }
 if(!parts){lastDivResult='';$('#divResult').textContent='Não é possível distribuir. O total precisa cobrir o mínimo de cada conta.';$('#divSum').textContent='Soma: —';return;}
 lastDivResult=output;
 $('#divResult').textContent=lastDivResult;
 $('#divSum').textContent='Soma: '+money(parts.reduce((a,b)=>a+b,0));
 const btn=document.querySelector('[data-action="distribute"]');if(btn)btn.innerHTML=ico('refresh')+' Distribuir novamente';
}
