function pageMyCommissions(){
 const c=myDebt(),week=selectedBillingWeek(),payments=D.payments.filter(p=>p.userId===D.me.id&&(p.billWeek||paymentWeekFromDate(p.at))===week).sort((a,b)=>String(b.at).localeCompare(String(a.at)));
 const history=D.billing.rows.filter(r=>r.userId===D.me.id).sort((a,b)=>b.weekStart.localeCompare(a.weekStart));
 return `${heading('Minhas Comissões','Acompanhe sua cobrança de 20% sobre o lucro líquido verde de cada operação da semana.')}<div class="notice"><span style="font-size:20px;color:var(--gold)">◈</span><div><strong>Seus valores são particulares</strong><p>Somente você vê suas operações aqui. O dono registra os pagamentos; os valores são calculados a partir do lucro líquido positivo de cada operação, sem cobrar de novo a taxa recebida pelos pedidos.</p></div></div>
 <section class="panel pad billing-period-panel"><div class="toolbar"><div><h3>Acumulado semanal</h3><p class="tiny">Cada lançamento lucrativo aumenta a cobrança; editar ou excluir atualiza o total.</p></div>${billingWeekPicker()}</div></section>
 <div class="grid cards4 stats my-debt-stats">${stat('Lucro positivo da semana',money(c.positiveProfit),'Somente operações lucrativas','green')}${stat('Comissão de 20%',money(c.owed),'Valor acumulado a pagar','gold')}${stat('Já pago nesta semana',money(c.paid),'Confirmado pelo dono','green')}${stat('Falta pagar nesta semana',money(c.pending),'Saldo da semana',c.pending>0?'red':'green')}</div>
 <section class="panel" style="margin-top:16px"><div class="paneltitle" style="padding:19px 19px 0"><div><h2>Operações que geraram cobrança</h2><p class="panelnote">${billingPeriodLabel(week)} • Montantes ${money(c.mont)} • Contas ${money(c.contas)}</p></div><span class="tag">${c.operations.length} registro(s)</span></div><div class="tablewrap"><table class="data-table"><thead><tr><th>Data</th><th>Tipo</th><th>Lucro líquido verde</th><th>Percentual</th><th>Comissão desta operação</th></tr></thead><tbody>${c.operations.length?c.operations.map(o=>`<tr><td class="tiny">${date(o.at)}</td><td><span class="tag">${safe(o.type==='contas'?'Contas':'Montante')}</span></td><td class="money ${o.netProfit>=0?'green':'red'}">${money(o.netProfit)}</td><td>20%</td><td class="money gold"><b>${money(o.commission)}</b></td></tr>`).join(''):`<tr><td colspan="5">${emptyInline('Nenhuma operação nesta semana.')}</td></tr>`}</tbody></table></div></section>
 <section class="panel pad" style="margin-top:16px"><div class="paneltitle"><h2>Pagamentos confirmados</h2><span class="tag good">${payments.length} recebido(s) nesta semana</span></div>${payments.length?payments.map(p=>`<div class="rowsmall"><div><b>${date(p.at)}</b><div class="tiny">${safe(p.notes||'Registrado pelo dono')}</div></div><b class="green">${money(p.amount)}</b></div>`).join(''):emptyInline('Ainda não há pagamento confirmado para esta semana.')}</section>
 <section class="panel" style="margin-top:16px"><div class="paneltitle" style="padding:19px 19px 0"><h2>Histórico de semanas</h2><span class="tag ${c.allPending>0?'warn':'good'}">Total pendente: ${money(c.allPending)}</span></div><div class="tablewrap"><table class="data-table"><thead><tr><th>Semana</th><th>Comissão</th><th>Recebido</th><th>Pendente</th></tr></thead><tbody>${history.length?history.map(r=>`<tr><td>${billingPeriodLabel(r.weekStart)}</td><td>${money(r.charged)}</td><td class="green">${money(r.paid)}</td><td class="${r.pending>0?'red':'green'}"><b>${money(r.pending)}</b></td></tr>`).join(''):`<tr><td colspan="4">${emptyInline('Nenhuma semana registrada.')}</td></tr>`}</tbody></table></div></section>
 <div class="callout" style="margin-top:14px"><strong>Pendente de todas as semanas: ${money(c.allPending)}</strong><p class="tiny" style="margin:6px 0 0">Uma semana nova começa na segunda-feira. Se ficar valor sem pagar, ele continua aparecendo no histórico.</p></div>`;
}
function paymentWeekFromDate(iso){let ds=new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Bahia',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(iso)),d=new Date(ds+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-(d.getUTCDay()+6)%7);return d.toISOString().slice(0,10);}
function pageCommissions(){let {sv,ops}=commRows(),valid=sv.filter(s=>s.status==='validado'),sum=round(valid.reduce((a,s)=>a+svcCommission(s),0)),acc=round(ops.reduce((a,o)=>a+accountsCommission(o),0)),salary=round(valid.reduce((a,s)=>a+s.salary,0));return `${heading('Serviços e comissões de pedidos',elevated()?'Acompanhe serviços e taxas de pedidos do WhatsApp, separadas da cobrança de 20% sobre o lucro.' :'Acompanhe serviços registrados.',elevated()?`<button class="btn primary" data-action="newservice">${ico('plus')} Registrar serviço</button>`:'')}<section class="panel pad" style="margin-bottom:14px"><div class="toolbar commission-filters"><div class="field"><label>Status</label><select id="statusFilter" class="input"><option value="all" ${statusFilter==='all'?'selected':''}>Todos</option><option value="validado" ${statusFilter==='validado'?'selected':''}>Validados</option><option value="pendente" ${statusFilter==='pendente'?'selected':''}>Pendentes</option><option value="anulado" ${statusFilter==='anulado'?'selected':''}>Anulados</option></select></div>${elevated()?`<div class="field"><label>Operador</label><select id="globalUser" class="input">${optUser(selectedUser)}</select></div>`:''}</div></section><div class="grid cards4 stats">${stat('Serviços validados',valid.length,'','green')}${stat('Salários recebidos',money(salary),'Dos serviços validados')}${stat('Comissão montantes',money(sum),'','gold')}${stat('Comissão contas',money(acc),'','gold')}</div><section class="panel"><div class="paneltitle" style="padding:19px 19px 0"><h2>Serviços de montante</h2><span class="tag">${sv.length} serviços</span></div><div class="tablewrap"><table class="data-table"><thead><tr><th>Data</th><th>Blogueira</th><th>Grupo</th>${elevated()?'<th>Operador</th>':''}<th>Montante</th><th>Salário</th><th>%</th><th>Comissão</th><th>Status</th>${elevated()?'<th>Ação</th>':''}</tr></thead><tbody>${sv.length?sv.map(s=>`<tr><td class="tiny">${date(s.createdAt)}</td><td>${safe(s.blogger||'—')}</td><td>${safe(s.group||'—')}</td>${elevated()?`<td>${safe(userName(s.userId))}</td>`:''}<td>${money(s.amount)}</td><td>${money(s.salary)}</td><td>${userById(s.userId).pctMontante||0}%</td><td class="gold money">${money(svcCommission(s))}</td><td><span class="tag ${s.status==='validado'?'good':s.status==='anulado'?'bad':'warn'}">${safe(s.status)}</span></td>${elevated()?`<td><button class="table-action" data-edit-service="${id(s.id)}">${ico('edit')}</button></td>`:''}</tr>`).join(''):`<tr><td colspan="10">${emptyInline('Nenhum serviço cadastrado neste filtro.')}</td></tr>`}</tbody></table></div></section><section class="panel" style="margin-top:15px"><div class="paneltitle" style="padding:19px 19px 0"><h2>Comissões registradas nas operações</h2><span class="tag">Informação de serviços; cobrança do lucro em Relatórios</span></div><div class="tablewrap"><table class="data-table"><thead><tr><th>Tipo</th><th>Data</th>${elevated()?'<th>Operador</th>':''}<th>Depósito</th><th>Saque</th><th>Blogueira / Salário</th><th>Lucro</th><th>Comissão</th></tr></thead><tbody>${ops.length?ops.slice(0,120).map(o=>`<tr><td><span class="tag">${isContas(o)?'Contas':'Montante'}</span></td><td>${date(o.createdAt)}</td>${elevated()?`<td>${safe(userName(o.userId))}</td>`:''}<td>${money(isContas(o)?accountValues(o).deposit:o.deposit)}</td><td>${money(isContas(o)?accountValues(o).withdraw:o.withdraw)}</td><td>${money(isContas(o)?accountValues(o).salary:o.blogger)}</td><td class="${profit(o)<0?'red':'green'}">${money(profit(o))}</td><td class="gold money">${money(accountsCommission(o))}</td></tr>`).join(''):`<tr><td colspan="8">${emptyInline('Nenhuma operação encontrada.')}</td></tr>`}</tbody></table></div></section>`;}
function inReportPeriod(dt){if(reportPeriod==='all')return true;let d=new Date(dt),start=new Date();start.setHours(0,0,0,0);if(reportPeriod==='today')return d>=start;if(reportPeriod==='week'){start.setDate(start.getDate()-6);return d>=start;}if(reportPeriod==='month')return d.getMonth()===start.getMonth()&&d.getFullYear()===start.getFullYear();return true;}
function reportRows(){return D.users.filter(u=>u.role!=='dono').map(u=>{let r=weeklyBill(u.id);return {u,owed:r.charged,paid:r.paid,pending:r.pending,operations:r.operationCount,profit:r.positiveProfit,entries:r.operations,allPending:allPendingFor(u.id)};});}
function pageReports(){
 const rows=reportRows(),owed=round(rows.reduce((a,r)=>a+r.owed,0)),paid=round(rows.reduce((a,r)=>a+r.paid,0)),pending=round(rows.reduce((a,r)=>a+r.pending,0)),totalPending=round(rows.reduce((a,r)=>a+r.allPending,0)),week=selectedBillingWeek();
 return `${heading('Relatórios e cobranças','Veja a comissão semanal de 20% sobre o lucro líquido verde de cada operador.',admin()?`<button class="btn" data-action="printreport">${ico('export')} Imprimir relatório</button>`:'')}
 <section class="panel pad" style="margin-bottom:15px"><div class="toolbar"><div><h3>Semana de apuração</h3><p class="tiny">Cobrança por operação lucrativa; pedido de WhatsApp não entra nessa base.</p></div>${billingWeekPicker()}</div></section>
 <div class="grid cards4 stats">${stat('Comissões da semana',money(owed),'20% do lucro líquido positivo','gold')}${stat('Já recebido',money(paid),'Pagamentos vinculados à semana','green')}${stat('Pendente nesta semana',money(pending),'Saldo em aberto',pending>0?'red':'green')}${stat('Pendente de todas as semanas',money(totalPending),'Inclui semanas anteriores','gold')}</div>
 <section class="panel" style="margin-top:16px"><div class="paneltitle" style="padding:19px 19px 0"><div><h2>Quanto cada operador deve pagar</h2><p class="panelnote">Semana ${billingPeriodLabel(week)} • Valores atualizados conforme cada operação salva</p></div><span class="tag">${rows.length} operador(es)</span></div>
 <div class="tablewrap"><table class="data-table billing-admin-table"><thead><tr><th>Operador</th><th>Operações</th><th>Lucro positivo</th><th>%</th><th>Total a cobrar</th><th>Já cobrado</th><th>Pendente</th><th>Ações</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td><b>${safe(r.u.name)}</b><div class="tiny">${safe(r.u.role)}</div></td><td>${r.operations}</td><td class="money green">${money(r.profit)}</td><td>20%</td><td class="money gold"><b>${money(r.owed)}</b></td><td class="money green">${money(r.paid)}</td><td class="money ${r.pending>0?'red':'green'}"><b>${money(r.pending)}</b></td><td class="billing-actions">${admin()?`<button class="btn sm" data-pay-user="${id(r.u.id)}" ${r.pending<=0?'disabled':''}>${ico('check')} Receber</button><button class="btn sm" data-copy-charge="${id(r.u.id)}" ${r.pending<=0?'disabled':''}>${ico('copy')} Cobrar</button>`:'<span class="tiny">Somente dono</span>'}</td></tr><tr class="billing-details-row"><td colspan="8"><details><summary>Ver operações de ${safe(r.u.name)} nesta semana (${r.entries.length})</summary><div class="billing-entry-list">${r.entries.length?r.entries.map(e=>`<span>${date(e.at)} • ${safe(e.type==='contas'?'Contas':'Montante')} • lucro ${money(e.netProfit)} • comissão <b>${money(e.commission)}</b></span>`).join(''):'<span>Sem operações nesta semana.</span>'}</div></details></td></tr>`).join(''):`<tr><td colspan="8">${emptyInline('Nenhum operador cadastrado.')}</td></tr>`}</tbody></table></div></section>
 <section class="panel pad" style="margin-top:16px"><div class="paneltitle"><h2>Pagamentos registrados da semana</h2></div>${D.payments.filter(p=>(p.billWeek||paymentWeekFromDate(p.at))===week).length?D.payments.filter(p=>(p.billWeek||paymentWeekFromDate(p.at))===week).slice().sort((a,b)=>String(b.at).localeCompare(String(a.at))).map(p=>`<div class="rowsmall"><div><b>${safe(userName(p.userId))}</b><div class="tiny">${date(p.at)} • ${safe(p.notes||'Recebido')}</div></div><strong class="green">${money(p.amount)}</strong></div>`).join(''):emptyInline('Nenhum pagamento confirmado nesta semana.')}</section>
 <div class="callout" style="margin-top:14px"><b>Regra do AR:</b> comissão de 20% somente sobre o lucro líquido positivo de cada operação (Saque − Depósito + Blogueira/Salário). Taxas recebidas por pedidos de WhatsApp não são cobradas novamente. As dívidas das semanas anteriores permanecem no histórico.</div>`;
}
function pageUsers(){return `${heading('Usuários','Controle os cadastros, cargos, contatos, metas e permissões da sua equipe.',`<button class="btn primary" data-action="newuser">${ico('plus')} Novo usuário</button>`)}<div class="notice"><span style="color:var(--gold)">✦</span><div><strong>Operadores vinculados ao WhatsApp</strong><p>Preencha o telefone com DDD para associar automaticamente os pedidos enviados pelo bot. Você pode modificar qualquer cadastro sem apagar o histórico.</p></div><button class="btn sm" data-nav="whatsapp">Pedidos ${ico('chev')}</button></div>
<section class="panel"><div class="tablewrap"><table class="data-table user-table"><thead><tr><th>Usuário</th><th>E-mail</th><th>Telefone</th><th>Tipo</th><th>% Montante</th><th>% Contas</th><th>Meta diária</th><th>Operações</th><th>Lucro</th><th>Status</th><th>Ações</th></tr></thead><tbody>${D.users.map(u=>{let op=D.operations.filter(o=>o.userId===u.id),t=totals(op);return `<tr><td><b>${safe(u.name)}</b></td><td class="tiny">${safe(u.email)}</td><td>${safe(u.phone||'—')}</td><td><span class="tag ${u.role==='dono'?'warn':''}">${safe(u.role)} • ${safe(u.kind)}</span></td><td>${u.pctMontante}%</td><td>${u.pctContas}%</td><td>${money(u.goal)}</td><td>${op.length}</td><td class="money ${t.profit<0?'red':'green'}">${money(t.profit)}</td><td><span class="tag ${u.active?'good':'bad'}">${u.active?'Ativo':'Inativo'}</span></td><td><div class="table-actions"><button class="btn sm" data-edit-user="${id(u.id)}" title="Editar usuário">${ico('edit')} Editar</button><button class="btn sm" data-user-detail="${id(u.id)}" title="Ver detalhes">${ico('search')}</button></div></td></tr>`;}).join('')}</tbody></table></div></section>`;}
function showUserDetail(u){let ops=D.operations.filter(o=>o.userId===u.id),sv=D.services.filter(s=>s.userId===u.id),ord=D.whatsappOrders.filter(o=>o.userId===u.id),t=totals(ops);modal=modalBox('Ficha do operador: '+u.name,`<div class="detail-grid"><div class="detail-tile"><span>Operações</span><strong>${ops.length}</strong></div><div class="detail-tile"><span>Lucro líquido</span><strong>${money(t.profit)}</strong></div><div class="detail-tile"><span>Pedidos WhatsApp</span><strong>${ord.length}</strong></div><div class="detail-tile"><span>Serviços validados</span><strong>${sv.filter(x=>x.status==='validado').length}</strong></div></div><p class="tiny">E-mail: ${safe(u.email)} • Telefone: ${safe(u.phone||'não informado')} • Cargo: ${safe(u.role)}</p><p class="tiny">Os registros continuam vinculados ao usuário, mesmo após alterações de nome, telefone ou percentuais.</p>`, 'Fechar');modalKind='detail';render();}

function pageAudit(){return `${heading('Atividades','Registro de criação, edição e ações administrativas.')}<section class="panel"><div class="tablewrap"><table class="data-table"><thead><tr><th>Data</th><th>Usuário</th><th>Ação</th><th>Detalhes</th></tr></thead><tbody>${D.audits.map(a=>`<tr><td>${date(a.at)}</td><td>${safe(a.actor)}</td><td><span class="tag">${safe(a.action)}</span></td><td>${safe(a.details)}</td></tr>`).join('')||`<tr><td colspan="4">${emptyInline('Nenhum evento registrado.')}</td></tr>`}</tbody></table></div></section>`;}

function pageSettings(){let s=D.settings;return `${heading('Configurações','Defina regras globais da calculadora e modelos de mensagens; cada usuário configura seu próprio PIX.')}<form class="grid" id="settingsForm" style="gap:14px"><section class="panel pad"><h2>Regras das calculadoras</h2><div class="formrow four">${field('Taxa padrão (%)','baseRate','number','20',true,s.baseRate)}${field('Montante mínimo promocional','promoAt','number','400',true,s.promoAt)}${field('Taxa promocional (%)','promoRate','number','18',true,s.promoRate)}${field('Meta diária geral','dailyGoal','number','1000',true,s.dailyGoal)}</div></section><section class="panel pad"><h2>PIX individual por operador</h2><p class="tiny">Cada usuário cadastra e altera a própria chave em <b>Meu PIX</b>. As regras e mensagens globais abaixo são administradas pelo dono.</p><button type="button" class="btn" data-nav="pix">${ico('copy')} Configurar meu PIX</button></section><section class="panel pad"><h2>Aviso do Dashboard</h2><div class="field"><label>Mensagem para toda a equipe</label><textarea name="announcement">${safe(s.announcement)}</textarea></div></section><div class="settingstack"><section class="panel pad"><h2>Template de montantes</h2><div class="field"><label>Variáveis: {montante}, {valor}, {contas}, {pix}, {nome}, {banco}</label><textarea name="templateMontante">${safe(s.templateMontante)}</textarea></div></section><section class="panel pad"><h2>Template de contas</h2><div class="field"><label>Variáveis: {contas}, {preco}, {total}, {pix}</label><textarea name="templateContas">${safe(s.templateContas)}</textarea></div></section></div><div style="display:flex;justify-content:flex-end"><button class="btn primary">${ico('check')} Salvar configurações</button></div></form>`;}

function pageWhatsApp(){let list=D.whatsappOrders||[],all=list.filter(o=>(orderStatus==='all'||o.status===orderStatus)&&(orderUser==='all'||o.userId===orderUser)),cnt=k=>list.filter(o=>o.status===k).length;let connected=D.botStatus?.connected;return `${heading('Pedidos WhatsApp','Acompanhe os pedidos do bot, quem aceitou, a comissão e o andamento.',`${elevated()?`<button class="btn" data-action="neworder">${ico('plus')} Pedido manual</button>`:''}<button class="btn" data-action="refresh">${ico('refresh')} Atualizar</button>`)}<div class="bot-alert ${connected?'connected':''}"><div class="bot-status-dot"></div><div style="flex:1"><strong>${connected?'Eventos recebidos do bot':'Aguardando o primeiro evento do bot'}</strong><div class="tiny">${connected?'Último evento: '+date(D.botStatus.lastEvent):'O painel está pronto, mas o bot não está conectado automaticamente.'} • Os registros podem ser atualizados a cada 20 segundos</div></div>${admin()?'<span class="tag">Configuração em LEIA-ME</span>':''}</div>
<div class="grid cards4 stats">${stat('Pedidos registrados',list.length,'Todos os pedidos visíveis','','▣')}${stat('Aceitos',cnt('aceito'),'Atribuídos aos operadores','blue','✓')}${stat('Validados',cnt('validado')+cnt('pago'),'Entram nos relatórios','green','↗')}${stat('Aguardando',cnt('recebido'),'Ainda não aceitos','gold','◷')}</div>
<section class="panel pad" style="margin-bottom:16px"><div class="toolbar"><div class="field"><label>Status do pedido</label><select id="orderStatus" class="input">${[['all','Todos'],['recebido','Recebidos'],['aceito','Aceitos'],['validado','Validados'],['pago','Pagos'],['anulado','Anulados']].map(([k,v])=>`<option value="${k}" ${orderStatus===k?'selected':''}>${v}</option>`).join('')}</select></div>${elevated()?`<div class="field"><label>Operador</label><select id="orderUser" class="input"><option value="all">Todos os operadores</option>${D.users.map(u=>`<option value="${id(u.id)}" ${orderUser===u.id?'selected':''}>${safe(u.name)}</option>`).join('')}</select></div>`:''}</div></section>
<section class="panel"><div class="tablewrap"><table class="data-table"><thead><tr><th>Data e hora</th><th>Blogueira</th><th>Grupo</th>${elevated()?'<th>Operador</th>':''}<th>Montante</th><th>Salário</th><th>Comissão</th><th>Status</th><th>Origem</th>${elevated()?'<th>Ações</th>':''}</tr></thead><tbody>${all.length?all.map(o=>`<tr><td class="tiny">${date(o.createdAt)}<div class="tiny">#${safe(o.requestId)}</div></td><td>${safe(o.blogger||'—')}</td><td>${safe(o.group||'—')}</td>${elevated()?`<td><b>${o.userId?safe(userName(o.userId)):'Sem vínculo'}</b><div class="tiny">${safe(o.operatorPhone||'')}</div></td>`:''}<td>${money(o.amount)}</td><td>${money(o.salary)}</td><td class="gold money">${money(['validado','pago'].includes(o.status)&&o.userId?round(o.salary*userById(o.userId).pctMontante/100):0)}</td><td><span class="tag ${o.status==='validado'||o.status==='pago'?'good':o.status==='anulado'?'bad':'warn'}">${safe(o.status)}</span></td><td class="tiny">${o.source==='manual'?'Manual':'Bot'}</td>${elevated()?`<td><button class="btn sm" data-edit-order="${id(o.id)}">${ico('edit')} Gerenciar</button></td>`:''}</tr>`).join(''):`<tr><td colspan="10">${emptyInline('Nenhum pedido encontrado. Envie eventos pelo conector do bot ou registre um pedido manualmente.')}</td></tr>`}</tbody></table></div><div class="table-footer">${all.length} pedido(s) encontrados • Os pedidos sem vínculo podem ser associados a um operador pelo ADM.</div></section>
<section class="panel pad" style="margin-top:16px"><div class="paneltitle"><h2>Como funciona a integração</h2><span class="tag">Autenticada</span></div><p class="tiny">Seu bot envia eventos de pedido recebido, aceito, validado, pago ou anulado para o endpoint local do AR. O sistema vincula o telefone do operador, guarda o histórico e atualiza a comissão de serviços validados. O token fica apenas no computador e no bot.</p><p class="tiny">Para conectar o bot que já usa WhatsApp, veja <b>LEIA-ME.txt</b> e <b>BOT-WHATSAPP.md</b> na pasta do sistema. Esta tela não acessa grupos do WhatsApp sem a integração configurada.</p></section>`;}

function modalBox(title,content,button='Salvar',formId='modalForm'){return `<div class="overlay" id="overlay"><div class="modal" role="dialog" aria-modal="true" aria-label="${safe(title)}"><div class="modal-head"><h2>${safe(title)}</h2><button type="button" class="ibtn" data-action="closemodal">${ico('close')}</button></div><form id="${formId}"><div class="modal-body">${content}</div><div class="modal-foot"><button type="button" class="btn" data-action="closemodal">Cancelar</button><button type="submit" class="btn primary">${ico('check')} ${safe(button)}</button></div></form></div></div>`;}
function openModal(type,obj=null){if(type==='newuser'||type==='edituser'){let u=obj||{},newOne=type==='newuser';modal=modalBox(newOne?'Criar novo usuário':'Editar usuário',`${field('Nome de usuário','name','text','Ex.: operador01',true,u.name||'')}${field('E-mail de acesso','email','email','operador@empresa.com',true,u.email||'')}${field('Telefone / WhatsApp','phone','tel','(00) 00000-0000',false,u.phone||'')}<div class="formrow two">${selectField('Cargo','role',newOne?[['operador','Operador padrão'],['gerente','Gerente']]:[['operador','Operador padrão'],['gerente','Gerente'],['dono','Dono / ADM']],u.role||'operador')}${selectField('Tipo de operador','kind',[['bi','Operador BI'],['montante','Operador de montante']],u.kind||'bi')}</div><div class="formrow three">${field('% Montante','pctMontante','number','10',true,u.pctMontante??10)}${field('% Contas','pctContas','number','10',true,u.pctContas??10)}${field('Meta diária','goal','number','1000',true,u.goal??1000)}</div>${newOne?field('Senha inicial (mín. 10 caracteres)','password','password','Senha segura',true):`${field('Nova senha (opcional)','password','password','Deixe vazio para manter')}${selectField('Status da conta','active',[['true','Ativo'],['false','Inativo']],String(u.active!==false))}`}`,newOne?'Criar usuário':'Salvar alterações');modalKind=type;modalObject=u.id;}
 else if(type==='newtable'||type==='edittable'){let t=obj||{};modal=modalBox(type==='newtable'?'Publicar novo material':'Editar material',`${field('Título da publicação','title','text','Tabela de montantes',true,t.title||'')}${selectField('Formato','kind',[['imagem','Imagem'],['pdf','PDF'],['texto','Texto']],t.kind||'imagem')}<div class="field"><label>Arquivo PNG, JPG, WEBP ou PDF (até 4 MB)</label><input type="file" name="upload" accept=".png,.jpg,.jpeg,.webp,.pdf"></div><div class="field"><label>Descrição / Texto</label><textarea name="description" placeholder="Insira um texto para os operadores consultarem...">${safe(t.description||'')}</textarea></div>${t.file?`<div class="tiny">Arquivo atual: ${safe(t.file)}</div>`:''}`,type==='newtable'?'Publicar material':'Salvar material');modalKind=type;modalObject=t.id;}
 else if(type==='newservice'||type==='editservice'){let s=obj||{},kind=type==='newservice';modal=modalBox(kind?'Registrar serviço de montante':'Editar serviço',`<div class="field"><label>Operador responsável</label><select name="userId">${optUser(s.userId||D.me.id,false)}</select></div><div class="formrow two">${field('Blogueira','blogger','text','Nome da blogueira',false,s.blogger||'')}${field('Grupo','group','text','Grupo / origem',false,s.group||'')}</div><div class="formrow two">${field('Montante (R$)','amount','number','500',true,s.amount??'')}${field('Salário pago (R$)','salary','number','90',true,s.salary??'')}</div>${selectField('Status do serviço','status',[['pendente','Pendente'],['validado','Validado'],['anulado','Anulado']],s.status||'pendente')}<div class="field"><label>Observações</label><textarea name="notes">${safe(s.notes||'')}</textarea></div><div class="callout tiny">Os serviços são lançados manualmente nesta versão. O bot do WhatsApp não está conectado.</div>`,kind?'Registrar serviço':'Salvar serviço');modalKind=type;modalObject=s.id;}
 else if(type==='neworder'||type==='editorder'){let o=obj||{},isNew=type==='neworder';let user= (o.userId&&D.users.some(u=>u.id===o.userId))?o.userId:D.me.id;modal=modalBox(isNew?'Registrar pedido manual':'Gerenciar pedido WhatsApp',`${isNew?field('ID único do pedido','requestId','text','Ex.: GRUPO-1234',true):`<div class="callout"><b>Pedido #${safe(o.requestId)}</b><div class="tiny">Origem: ${safe(o.source||'bot')} • ${date(o.createdAt)}</div></div>`}<div class="field"><label>Operador responsável</label><select name="userId"><option value="">Sem vínculo</option>${optUser(user,false)}</select></div>${isNew?`<div class="formrow two">${field('Blogueira','blogger','text','Nome',false,'')}${field('Grupo','group','text','Nome do grupo',false,'')}</div><div class="formrow two">${field('Montante','amount','number','100',true,0)}${field('Salário','salary','number','20',true,0)}</div>`:''}${selectField('Status do pedido','status',[['recebido','Recebido'],['aceito','Aceito'],['validado','Validado'],['pago','Pago'],['anulado','Anulado']],o.status||'recebido')}<div class="field"><label>Observações</label><textarea name="notes" maxlength="500">${safe(o.notes||'')}</textarea></div>${isNew?'':`<div class="timeline"><h3>Histórico do pedido</h3>${(o.events||[]).slice().reverse().map(e=>`<div class="tiny">${date(e.at)} — ${safe(e.type)} por ${safe(e.actor)}</div>`).join('')||'<div class="tiny">Nenhuma alteração.</div>'}</div>`}`,isNew?'Criar pedido':'Salvar pedido');modalKind=type;modalObject=o.id;}
 else if(type==='payment'){let u=obj;let row=reportRows().find(r=>r.u.id===u.id);modal=modalBox('Registrar pagamento recebido',`<div class="callout"><strong>${safe(u.name)}</strong><div class="tiny">Semana ${billingPeriodLabel(selectedBillingWeek())} • Cobrado ${money(row.owed)} | Já recebido ${money(row.paid)} | Pendente ${money(row.pending)}</div></div>${field('Valor recebido (R$)','amount','number','0,00',true,Math.max(0,row.pending))}<div class="field"><label>Observação</label><textarea name="notes" placeholder="Ex.: PIX recebido no dia ..."></textarea></div><div class="tiny">Este registro será somado ao histórico. Não substitui o pagamento anterior.</div>`,'Confirmar recebimento');modalKind=type;modalObject=u.id;}
 render();}
let modalKind='',modalObject=null;
async function fileBase64(file){return new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('Erro ao ler o arquivo.'));reader.readAsDataURL(file);});}
async function saveModal(form){let data=Object.fromEntries(new FormData(form));if(modalKind==='newuser'||modalKind==='edituser'){for(let f of ['goal','pctMontante','pctContas'])data[f]=Number(data[f]||0);if(modalKind==='edituser'){if(!data.password)delete data.password;data.active=data.active==='true';await api('/users/'+modalObject,{method:'PATCH',body:JSON.stringify(data)});}else await api('/users',{method:'POST',body:JSON.stringify(data)});}
 else if(modalKind==='newtable'||modalKind==='edittable'){let file=form.elements.upload.files[0];if(file){if(file.size>4*1024*1024)throw new Error('O arquivo precisa ter até 4 MB.');let r=await api('/uploads',{method:'POST',body:JSON.stringify({name:file.name,mime:file.type,data:await fileBase64(file)})});data.file=r.url;}delete data.upload;if(modalKind==='newtable')await api('/tables',{method:'POST',body:JSON.stringify(data)});else await api('/tables/'+modalObject,{method:'PATCH',body:JSON.stringify(data)});}
 else if(modalKind==='newservice'||modalKind==='editservice'){data.amount=Number(data.amount);data.salary=Number(data.salary);await api(modalKind==='newservice'?'/services':'/services/'+modalObject,{method:modalKind==='newservice'?'POST':'PATCH',body:JSON.stringify(data)});}
 else if(modalKind==='neworder'){for(let k of ['amount','salary'])data[k]=Number(data[k]||0);await api('/whatsapp/orders',{method:'POST',body:JSON.stringify(data)});}
 else if(modalKind==='editorder'){await api('/whatsapp/orders/'+modalObject,{method:'PATCH',body:JSON.stringify({userId:data.userId||undefined,status:data.status,notes:data.notes})});}
 else if(modalKind==='payment'){await api('/payments',{method:'POST',body:JSON.stringify({userId:modalObject,billWeek:selectedBillingWeek(),amount:Number(data.amount),notes:data.notes})});}
 modal='';modalKind='';await load();notify('Alterações salvas com sucesso.');}
async function copyText(t){try{await navigator.clipboard.writeText(t);notify('Copiado para a área de transferência!');}catch{let a=document.createElement('textarea');a.value=t;document.body.appendChild(a);a.select();document.execCommand('copy');a.remove();notify('Texto copiado!');}}
function download(name,body,mime){let blob=new Blob([body],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1200);}
function exports(type){
 if(!elevated()){notify('Exportação disponível somente para a administração.',true);return;}
 let ops=selOp(),rows=ops.map(o=>({tipo:isContas(o)?'Contas':'Montante',usuario:userName(o.userId),depositoMontante:isContas(o)?0:Number(o.deposit||0),saqueMontante:isContas(o)?0:Number(o.withdraw||0),blogueira:isContas(o)?0:Number(o.blogger||0),depositoContas:isContas(o)?accountValues(o).deposit:0,saqueContas:isContas(o)?accountValues(o).withdraw:0,salarioContas:isContas(o)?accountValues(o).salary:0,lucroBruto:round(gross(o)),lucroLiquido:round(profit(o)),comissaoContas:accountsCommission(o),anotacoes:o.notes,dataCriacao:o.createdAt,dataAlteracao:o.updatedAt})),name='AR-OPERACOES-'+new Date().toISOString().slice(0,10);
 if(type==='json')return download(name+'.json',JSON.stringify(rows,null,2),'application/json');
 if(type==='csv'){let header=Object.keys(rows[0]||{tipo:'',usuario:'',depositoMontante:'',saqueMontante:'',blogueira:'',depositoContas:'',saqueContas:'',salarioContas:'',lucroBruto:'',lucroLiquido:'',comissaoContas:'',anotacoes:'',dataCriacao:'',dataAlteracao:''});let vals=rows.map(r=>header.map(k=>'"'+String(r[k]??'').replaceAll('"','""')+'"').join(';'));return download(name+'.csv','\ufeff'+header.join(';')+'\r\n'+vals.join('\r\n'),'text/csv;charset=utf-8');}
 window.print();
}
async function onAction(action){if(action==='side'){if(window.matchMedia('(max-width:760px)').matches){mobileMenuOpen=!mobileMenuOpen;}else{collapsed=!collapsed;localStorage.setItem('ar_side',collapsed?'1':'0');}render();}else if(action==='palette'){themeMenuOpen=!themeMenuOpen;render();}else if(action==='logout'){await api('/logout',{method:'POST',body:'{}'});D=null;renderAuth('login');}else if(action==='openpix'){calcOpen=true;pixEditOpen=true;calcTab='montante';localStorage.setItem('ar_calc','1');render();document.querySelector('.calculator-pix-card')?.scrollIntoView({behavior:'smooth',block:'center'});}else if(action==='togglecalc'){calcOpen=!calcOpen;localStorage.setItem('ar_calc',calcOpen?'1':'0');render();}else if(action==='cancel-edit'){editOp=null;render();}else if(action==='use-blogger'){let f=$('#montanteForm');if(!f)return;let dep=Number(f.elements.deposit.value||0),pct=suggestionRate(dep);if(dep<=0||![18,20].includes(pct))return;let v=round(dep*pct/100);f.elements.blogger.value=v.toFixed(2);updateOpPreview(f);notify('Sugestão aplicada ao campo Blogueira.');}else if(action==='copycalc'){if(calcTab==='montante'&&!(Number($('[name="calcAmount"]')?.value)>0)){notify('Digite o montante do pedido antes de copiar.',true);return;}if(!ownP().key){notify('Cadastre sua chave PIX antes de copiar a mensagem.',true);pixEditOpen=true;render();}else await copyText(calcValue());}else if(action==='editpix'){pixEditOpen=!pixEditOpen;render();}else if(action==='distribute'){calcDivider();}else if(action==='copydiv'){if(!lastDivResult)calcDivider();if(lastDivResult)await copyText(lastDivResult);}else if(action==='period-custom'){customStart=$('#customStart')?.value||'';customEnd=$('#customEnd')?.value||'';render();}else if(action==='csv'||action==='json'||action==='print'){exports(action);}else if(action==='printreport'){window.print();}else if(action==='newuser'){openModal('newuser');}else if(action==='newtable'){openModal('newtable');}else if(action==='newservice'){openModal('newservice');}else if(action==='neworder'){openModal('neworder');}else if(action==='refresh'){await load();notify('Dados atualizados.');}else if(action==='editsettings'){screen='settings';render();}else if(action==='closemodal'){modal='';render();}}
document.addEventListener('click',async e=>{if(themeMenuOpen&&!e.target.closest('.theme-picker')){themeMenuOpen=false;render();return;}let b=e.target.closest('button,a');if(!b)return;try{if(b.dataset.themeId){
 const chosen=b.dataset.themeId;
 if(!palettes.some(p=>p.id===chosen))return;
 await api('/me/theme',{method:'PATCH',body:JSON.stringify({theme:chosen})});
 theme=chosen; D.me.theme=chosen;themeMenuOpen=false;applyTheme();render();notify('Tema salvo para sua conta.');return;
 }
 if(b.dataset.nav){themeMenuOpen=false;let which=b.dataset.nav;if(!visibleNav().some(x=>x.id===which))return;screen=which;period='all';selectedUser='all';editOp=null;modal='';mobileMenuOpen=false;render();window.scrollTo(0,0);return;}
 if(b.dataset.action){await onAction(b.dataset.action);return;}
 if(b.dataset.period){period=b.dataset.period;render();return;}
 if(b.dataset.rankPeriod){adminRankPeriod=b.dataset.rankPeriod;render();return;}
 if(b.dataset.reportPeriod){reportPeriod=b.dataset.reportPeriod;render();return;}
 if(b.dataset.opTab){const requested=b.dataset.opTab;if(!['montante','contas'].includes(requested))return;activeOperationTab=requested;editOp=null;render();return;}
 if(b.dataset.calcTab){calcTab=b.dataset.calcTab;render();return;}
 if(b.dataset.editOp){editOp=D.operations.find(o=>o.id===b.dataset.editOp);if(!editOp)return;activeOperationTab=isContas(editOp)?'contas':'montante';screen='operations';render();document.getElementById('newOperation')?.scrollIntoView({behavior:'smooth',block:'start'});return;}
 if(b.dataset.delOp){if(!confirm('Excluir esta operação? Ela deixará de aparecer nos relatórios, mas o evento será registrado na auditoria.'))return;await api('/operations/'+b.dataset.delOp,{method:'DELETE',body:'{}'});editOp=null;await load();notify('Operação excluída.');return;}
 if(b.dataset.editUser){openModal('edituser',D.users.find(u=>u.id===b.dataset.editUser));return;}
  if(b.dataset.userDetail){showUserDetail(D.users.find(u=>u.id===b.dataset.userDetail));return;}
  if(b.dataset.editOrder){openModal('editorder',D.whatsappOrders.find(o=>o.id===b.dataset.editOrder));return;}
 if(b.dataset.payUser){openModal('payment',D.users.find(u=>u.id===b.dataset.payUser));return;}
 if(b.dataset.copyCharge){let row=reportRows().find(r=>r.u.id===b.dataset.copyCharge);if(!row)return;await copyText(`AR Contas & Montantes\nOperador: ${row.u.name}\nSemana: ${billingPeriodLabel(selectedBillingWeek())}\nComissão de 20% do lucro: ${money(row.owed)}\nJá pago: ${money(row.paid)}\nSaldo pendente: ${money(row.pending)}`);return;}
 if(b.dataset.editService){openModal('editservice',D.services.find(s=>s.id===b.dataset.editService));return;}
 if(b.dataset.editTable){openModal('edittable',D.tables.find(t=>t.id===b.dataset.editTable));return;}
 if(b.dataset.deleteTable){if(!confirm('Excluir esta publicação?'))return;await api('/tables/'+b.dataset.deleteTable,{method:'DELETE',body:'{}'});await load();notify('Publicação excluída.');return;}
 if(b.dataset.openTable){let t=D.tables.find(x=>x.id===b.dataset.openTable);if(t.file)window.open(t.file,'_blank','noopener');else await copyText(t.description||t.title);return;}
 if(b.dataset.copyTable){let t=D.tables.find(x=>x.id===b.dataset.copyTable);await copyText(t.description||t.title);return;}
 }catch(err){notify(err.message,true);}});
document.addEventListener('change',e=>{
 if(e.target.name==='percentBlogger'&&e.target.closest('#montanteForm'))updateOpPreview(e.target.form);
 else if(e.target.id==='globalUser'){selectedUser=e.target.value;render();}
 else if(e.target.id==='billingWeekSelect'){billingWeek=e.target.value;render();}
 else if(e.target.id==='statusFilter'){statusFilter=e.target.value;render();}
 else if(e.target.id==='orderStatus'){orderStatus=e.target.value;render();}
 else if(e.target.id==='orderUser'){orderUser=e.target.value;render();}
});
function updateOpPreview(f){if(!f)return;let m=Object.fromEntries(new FormData(f));
 if(f.id==='montanteForm'){
  let g=Number(m.withdraw||0)-Number(m.deposit||0),pr=g+Number(m.blogger||0);
  let ge=$('#grossPreviewMont'),pe=$('#profitPreviewMont'),ce=$('#commissionPreviewMont'),se=$('#suggestLabel');
  if(ge)ge.textContent=money(g);if(pe){pe.textContent=money(pr);pe.className='money '+(pr>=0?'green':'red');}if(ce)ce.textContent=money(admin()?0:round(Math.max(0,pr)*.2));
  let dep=Number(m.deposit||0),pct=dep>0?suggestionRate(dep):0,visible=dep>0&&[18,20].includes(pct),sw=$('#suggestWrap');if(f.elements.percentBlogger)f.elements.percentBlogger.value=pct;
  if(sw)sw.classList.toggle('hide',!visible);
  if(se&&visible)se.textContent=money(round(dep*pct/100))+' ('+nr(pct)+'%)';
 }else if(f.id==='contasForm'){
  let ent=Number(m.accountDeposit||0)+Number(m.accountSalary||0);
  let pr=Number(m.accountWithdraw||0)-Number(m.accountDeposit||0)+Number(m.accountSalary||0);
  let a=$('#entryPreviewCont'),p=$('#profitPreviewCont'),c=$('#commissionPreviewCont');
  if(a)a.textContent=money(ent);if(p){p.textContent=money(pr);p.className='money '+(pr>=0?'green':'red');}if(c)c.textContent=money(admin()?0:round(Math.max(0,pr)*.2));
 }
}
document.addEventListener('input',e=>{
 let name=e.target.name;
 if(['calcAmount','calcCount','calcMin','calcMax','calcUnit'].includes(name)){calcValue();return;}
 if(e.target.closest('#montanteForm')&&['deposit','withdraw','blogger'].includes(name)){if(name==='deposit'&&e.target.form.dataset.lastDeposit!==e.target.value){e.target.form.elements.blogger.value='';e.target.form.dataset.lastDeposit=e.target.value;}updateOpPreview(e.target.form);}
 if(e.target.closest('#contasForm')&&['accountDeposit','accountWithdraw','accountSalary'].includes(name))updateOpPreview(e.target.form);
});
document.addEventListener('submit',async e=>{
 let f=e.target;if(!['montanteForm','contasForm','settingsForm','modalForm','pixForm'].includes(f.id))return;
 e.preventDefault();let button=f.querySelector('[type=submit]');if(button)button.disabled=true;
 try{
  if(['montanteForm','contasForm'].includes(f.id)){
   let b=Object.fromEntries(new FormData(f));b.type=f.dataset.opType;
   for(let k of ['deposit','withdraw','blogger','accountDeposit','accountWithdraw','accountSalary','percentBlogger'])if(k in b)b[k]=Number(b[k]||0);
   let old=editOp&&((isContas(editOp)&&b.type==='contas')||(!isContas(editOp)&&b.type==='montante'))?editOp:null;
   await api(old?'/operations/'+old.id:'/operations',{method:old?'PATCH':'POST',body:JSON.stringify(b)});
   editOp=null;await load();notify(b.type==='contas'?'Resultado de Contas salvo no histórico separado.':'Montante salvo no histórico separado.');
  }else if(f.id==='pixForm'){
   let b=Object.fromEntries(new FormData(f));await api('/me/pix',{method:'PATCH',body:JSON.stringify(b)});pixEditOpen=false;await load();notify('Seu PIX foi salvo apenas na sua conta.');
  }else if(f.id==='settingsForm'){
   let b=Object.fromEntries(new FormData(f));for(let k of ['promoAt','promoRate','baseRate','dailyGoal'])b[k]=Number(b[k]);
   await api('/settings',{method:'PATCH',body:JSON.stringify(b)});await load();notify('Configurações atualizadas para toda a equipe.');
  }else await saveModal(f);
 }catch(err){notify(err.message,true);}finally{if(button)button.disabled=false;}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(modal){modal='';render();}else if(themeMenuOpen){themeMenuOpen=false;render();}}});
setInterval(async()=>{if(D&&screen==='whatsapp'&&!modal&&document.visibilityState==='visible'){try{D=await api('/bootstrap');render();}catch(e){console.warn('Atualização dos pedidos falhou:',e.message);}}},20000);
init().catch(e=>{$('#app').innerHTML=`<div class="initial"><div><h2>Não foi possível abrir o sistema.</h2><p>${safe(e.message)}</p><button class="btn" onclick="location.reload()">Tentar novamente</button></div></div>`;});
